(()=>{const $=id=>document.getElementById(id),E=AsnyaEngine,pct=x=>(x*100).toFixed(2)+'%';let result,rows,experiments=[],custom=null;try{experiments=JSON.parse(localStorage.getItem('asnya-runs')||'[]');custom=JSON.parse(localStorage.getItem('asnya-data')||'null')}catch{}function persist(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{$('runmsg').textContent='Storage unavailable. Export results to keep them.'}}function showTab(id){['lab','portfolio','runs','data','guide'].forEach(x=>$(x).classList.toggle('hidden',x!==id));document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===id));$('crumb').textContent={lab:'Research lab',portfolio:'Portfolio desk',runs:'Experiment ledger',data:'Data workspace',guide:'Methodology'}[id]}document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>showTab(b.dataset.tab));function customOption(){if(!$('dataset').querySelector('[value="custom"]'))$('dataset').add(new Option('Imported · daily prices','custom'))}if(custom)customOption();function table(list){return '<table><thead><tr><th>EXPERIMENT</th><th>DATASET</th><th>WINDOWS</th><th>COST</th><th>RETURN</th><th>SHARPE</th><th>MAX DD</th></tr></thead><tbody>'+list.map(r=>`<tr><td>${r.strategy==='trend'?'Trend following':'Mean reversion'}<br><span class="sub">${r.stamp} · ${r.fingerprint} · v0.2</span></td><td>${r.dataset==='custom'?'Imported':r.dataset==='trend'?'Synthetic trend':'Synthetic chop'}</td><td>${r.fast} / ${r.slow}</td><td>${r.cost} bps</td><td class="green">${pct(r.total)}</td><td>${r.sharpe.toFixed(2)}</td><td>${pct(r.dd)}</td></tr>`).join('')+'</tbody></table>'}function tables(){$('recent').innerHTML=table(experiments.slice(0,4));$('ledger').innerHTML=experiments.length?table(experiments):'<p class="empty">No experiments yet. Run one in the research lab.</p>'}function chart(id,series,height,draw=false){let all=series.flatMap(s=>s.values),min=Math.min(...all),max=Math.max(...all);if(draw)max=0;let spread=max-min||1;min-=spread*.08;max+=spread*.08;const x=i=>48+i/(series[0].values.length-1)*780,y=v=>15+(max-v)/(max-min)*(height-45);let html='';for(let i=0;i<4;i++){let v=min+(max-min)*i/3,yy=y(v);html+=`<line x1="48" x2="828" y1="${yy}" y2="${yy}" stroke="#293538"/><text x="0" y="${yy+4}" fill="#93a6aa" font-family="monospace" font-size="10">${draw?(v*100).toFixed(0)+'%':v.toFixed(0)}</text>`}series.forEach(s=>{html+=`<path d="${s.values.map((v,i)=>(i?'L':'M')+x(i).toFixed(2)+','+y(v).toFixed(2)).join(' ')}" fill="none" stroke="${s.color}" stroke-width="2" ${s.dash?'stroke-dasharray="5 5"':''}/>`});html+=`<text x="48" y="${height-2}" fill="#93a6aa" font-size="10" font-family="monospace">${result.out[0].date}</text><text x="828" y="${height-2}" text-anchor="end" fill="#93a6aa" font-size="10" font-family="monospace">${result.out.at(-1).date}</text>`;$(id).innerHTML=html}function fingerprint(rows){let h=2166136261;for(const c of JSON.stringify(rows))h=Math.imul(h^c.charCodeAt(0),16777619);return(h>>>0).toString(16).padStart(8,'0')}function run(save=true){try{let params={fast:+$('fast').value,slow:+$('slow').value,cost:+$('cost').value,strategy:$('strategy').value};rows=$('dataset').value==='custom'?custom:E.synthetic($('dataset').value);result=E.backtest(rows,params);$('metrics').innerHTML=[['Total return',pct(result.total),'NET OF TRADING COSTS'],['Annualized return',pct(result.cagr),'252 OBSERVATIONS / YEAR'],['Sharpe ratio',result.sharpe.toFixed(2),'ZERO RISK-FREE RATE'],['Max drawdown',pct(result.dd),result.turns+' POSITION CHANGES']].map(([label,value,sub])=>`<div class="metric"><div class="label">${label}</div><div class="value ${label==='Max drawdown'?'':'green'}">${value}</div><div class="sub">${sub}</div></div>`).join('');chart('equity',[{values:result.out.map(x=>x.equity),color:'#c5ee89'},{values:result.out.map(x=>x.benchmark),color:'#7f969e',dash:true}],310);chart('drawdown',[{values:result.out.map(x=>x.drawdown),color:'#e9a294'}],100,true);if(save){experiments.unshift({...params,dataset:$('dataset').value,total:result.total,sharpe:result.sharpe,dd:result.dd,stamp:new Date().toISOString().slice(0,19).replace('T',' ')+' UTC',fingerprint:fingerprint(rows)});experiments=experiments.slice(0,100);persist('asnya-runs',experiments)}tables();$('runmsg').textContent=`Complete · ${rows.length} observations · ${result.out.length-1} evaluated returns. ${$('dataset').value==='custom'?'Imported data.':'Synthetic data · seed 42.'}`}catch(e){$('runmsg').textContent=e.message}}$('config').onsubmit=e=>{e.preventDefault();run()};function download(name,text){let url=URL.createObjectURL(new Blob([text],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}$('export').onclick=()=>download('asnya-street-results.csv','date,close,position,equity,benchmark,drawdown\n'+result.out.map(r=>[r.date,r.close,r.position,r.equity,r.benchmark,r.drawdown].join(',')).join('\n'));$('sample').onclick=()=>download('asnya-synthetic-prices.csv','date,close\n'+E.synthetic('trend').map(r=>r.date+','+r.close).join('\n'));$('upload').onchange=async e=>{try{let file=e.target.files[0];if(!file)return;if(file.size>3000000)throw Error('Maximum file size is 3 MB.');custom=E.parseCSV(await file.text());persist('asnya-data',custom);customOption();$('dataset').value='custom';$('uploadmsg').textContent=`Imported ${custom.length} daily prices. Selected in Research lab.`;showTab('lab');run()}catch(err){$('uploadmsg').textContent=err.message}};$('clear').onclick=()=>{experiments=[];persist('asnya-runs',experiments);tables()};run(false);

window.showTab=showTab;})();
(()=>{const d=document.getElementById('command-dialog');document.getElementById('commands').onclick=()=>d.showModal();document.getElementById('close-commands').onclick=()=>d.close();d.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{window.showTab(b.dataset.go);d.close()});document.getElementById('command-run').onclick=()=>{d.close();window.showTab('lab');document.getElementById('config').requestSubmit()};document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();d.open?d.close():d.showModal()}})})();

(()=>{
 const $=id=>document.getElementById(id),E=AsnyaEngine,usd=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n),pct=n=>n===null?'—':(n*100).toFixed(2)+'%';
 const empty=()=>({version:1,currency:'USD',cash:0,holdings:[]});let book=empty();const message=t=>{$('portfolio-message').textContent=t};
 try{const saved=localStorage.getItem('asnya-portfolio-v1');if(saved)book=E.validatePortfolio(JSON.parse(saved))}catch{message('Saved portfolio could not be loaded. Import an exported copy to restore it.')}
 function save(){try{localStorage.setItem('asnya-portfolio-v1',JSON.stringify(book));message('Portfolio saved locally. Prices are manually entered.')}catch{message('Browser storage unavailable. Export to preserve your portfolio.')}render()}
 function render(){const r=E.portfolioSummary(book);$('portfolio-cash').value=book.cash;
 $('portfolio-metrics').innerHTML=[['Portfolio value',usd(r.total),'HOLDINGS + CASH'],['Unrealized P&L',usd(r.pnl),pct(r.pnlPercent)+' ON POSITION COST'],['Invested capital',usd(r.invested),usd(r.cash)+' CASH'],['Largest holding',pct(r.largestWeight),r.holdings.length+' POSITIONS']].map(([a,b,c])=>`<div class="metric"><div class="label">${a}</div><div class="value">${b}</div><div class="sub">${c}</div></div>`).join('');
 $('positions').innerHTML=r.holdings.length?'<table><thead><tr><th>SYMBOL</th><th>QTY</th><th>PRICE</th><th>VALUE</th><th>UNREALIZED P&L</th><th>WEIGHT</th><th>ACTIONS</th></tr></thead><tbody>'+r.holdings.map(h=>`<tr><td>${h.symbol}</td><td>${h.quantity}</td><td>${usd(h.price)}</td><td>${usd(h.value)}</td><td class="${h.pnl<0?'negative':'positive'}">${usd(h.pnl)}</td><td>${pct(h.weight)}</td><td><button class="secondary book-action" data-edit="${h.symbol}">Edit</button> <button class="secondary book-action" data-remove="${h.symbol}">Remove</button></td></tr>`).join('')+'</tbody></table>':'<p class="empty">No holdings yet. Add a position or load the fictional example.</p>';
 $('positions').querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const h=book.holdings.find(h=>h.symbol===b.dataset.edit);for(const [id,k]of [['holding-symbol','symbol'],['holding-quantity','quantity'],['holding-cost','cost'],['holding-price','price']])$(id).value=h[k];$('holding-symbol').focus()});
 $('positions').querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{book.holdings=book.holdings.filter(h=>h.symbol!==b.dataset.remove);save()});
 $('allocation').innerHTML=[...r.holdings.map(h=>({symbol:h.symbol,weight:h.weight})),{symbol:'CASH',weight:r.total?r.cash/r.total:0}].map(h=>`<div class="allocation-row"><span>${h.symbol}</span><div class="allocation-track"><div class="allocation-fill" style="width:${h.weight*100}%"></div></div><span>${pct(h.weight)}</span></div>`).join('');
 $('shock-target').replaceChildren(new Option('All holdings','all'),...book.holdings.map(h=>new Option(h.symbol,h.symbol)));$('shock-result').textContent='Choose a price change to see the portfolio impact.';
 }
 $('holding-form').onsubmit=e=>{e.preventDefault();try{const symbol=$('holding-symbol').value.trim().toUpperCase(),h={symbol,quantity:+$('holding-quantity').value,cost:+$('holding-cost').value,price:+$('holding-price').value};const next={...book,holdings:[...book.holdings.filter(x=>x.symbol!==symbol),h]};book=E.validatePortfolio(next);save();e.target.reset()}catch(err){message(err.message)}};
 $('cash-form').onsubmit=e=>{e.preventDefault();try{book=E.validatePortfolio({...book,cash:+$('portfolio-cash').value});save()}catch(err){message(err.message)}};
 $('shock-form').onsubmit=e=>{e.preventDefault();try{const r=E.stressPortfolio(book,+$('shock-percent').value,$('shock-target').value);$('shock-result').innerHTML=`<div class="label">SCENARIO PORTFOLIO VALUE</div><div class="scenario-value">${usd(r.after)}</div><p class="${r.delta<0?'negative':'positive'}">${usd(r.delta)} · ${pct(r.change)} of current value</p><p class="notice">${r.percent}% price change · ${r.target==='all'?'all holdings':r.target}. Cash unchanged. Hypothetical instantaneous shock; no probability, correlation, liquidity or execution model.</p>`}catch(err){message(err.message)}};
 $('portfolio-demo').onclick=()=>{book={version:1,currency:'USD',cash:2000,holdings:[{symbol:'DEMO-A',quantity:50,cost:100,price:110},{symbol:'DEMO-B',quantity:20,cost:200,price:180}]};save();message('Fictional example loaded. These are not market quotes.')};
 $('portfolio-export').onclick=()=>{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(book,null,2)],{type:'application/json'}));a.href=url;a.download='asnya-portfolio.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
 $('portfolio-import').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>100000)throw Error('Portfolio JSON must be smaller than 100 KB');const next=E.validatePortfolio(JSON.parse(await f.text()));book=next;save()}catch(err){message('Import rejected: '+err.message)}finally{e.target.value=''}};
 render();
})();
